#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <array>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
using namespace fedspatial; namespace fs=std::filesystem;
namespace {
Matrix load(const fs::path&p){Matrix x;if(!read_matrix(p.string(),&x))throw std::runtime_error("missing "+p.string());return x;}
WorkerInput worker(const fs::path&f,int id){Matrix d=load(f/("worker_"+std::to_string(id)+".txt"));WorkerInput w{Matrix(d.rows,2),Matrix(d.rows,1),Matrix(d.rows,d.cols-3)};for(int i=0;i<d.rows;i++){w.sites(i,0)=d(i,0);w.sites(i,1)=d(i,1);w.z(i,0)=d(i,2);for(int j=0;j<w.x.cols;j++)w.x(i,j)=d(i,j+3);}return w;}
void add(Matrix&a,const Matrix&b,double s=1){for(int i=0;i<a.rows*a.cols;i++)a.a[i]+=s*b.a[i];}
double tr(const Matrix&a){double x=0;for(int i=0;i<a.rows;i++)x+=a(i,i);return x;}
double dot(const Matrix&a,const Matrix&b){double x=0;for(int i=0;i<a.rows*a.cols;i++)x+=a.a[i]*b.a[i];return x;}
double err(const Matrix&a,const Matrix&b){return max_abs_diff(a,b);}
struct Eig { Matrix v; std::array<double,3> d; };
Eig jacobi(Matrix a){Matrix v=identity(3);for(int it=0;it<64;it++){int p=0,q=1;double mx=std::abs(a(0,1));for(int i=0;i<3;i++)for(int j=i+1;j<3;j++)if(std::abs(a(i,j))>mx){mx=std::abs(a(i,j));p=i;q=j;}if(mx<1e-15)break;double phi=.5*std::atan2(2*a(p,q),a(q,q)-a(p,p)),c=std::cos(phi),s=std::sin(phi);for(int k=0;k<3;k++){double apk=a(p,k),aqk=a(q,k);a(p,k)=c*apk-s*aqk;a(q,k)=s*apk+c*aqk;}for(int k=0;k<3;k++){double akp=a(k,p),akq=a(k,q);a(k,p)=c*akp-s*akq;a(k,q)=s*akp+c*akq;double vkp=v(k,p),vkq=v(k,q);v(k,p)=c*vkp-s*vkq;v(k,q)=s*vkp+c*vkq;}}Eig e{v,{a(0,0),a(1,1),a(2,2)}};std::array<int,3> ix{0,1,2};std::sort(ix.begin(),ix.end(),[&](int x,int y){return e.d[x]<e.d[y];});Matrix vv(3,3);std::array<double,3> dd{};for(int j=0;j<3;j++){dd[j]=e.d[ix[j]];for(int i=0;i<3;i++)vv(i,j)=v(i,ix[j]);}return {vv,dd};}
}
int main(){try{fs::path f="sync_gpu/tests/fixtures/figure1_reference",o="results/figure1_cpp_gpu_faithful/parity";fs::create_directories(o);Matrix knots=load(f/"knots.txt"),mu=load(f/"p_initial_global_mu.txt"),sig=load(f/"p_initial_global_sigma.txt"),gamma=load(f/"p_initial_gamma_new.txt");GlobalParameters p{gamma,mu,sig,.25,1,.11};GpuContext c(0);Matrix lg(3,1),lh(3,3);for(int id=0;id<10;id++){auto r=compute_delta_theta_local(c,worker(f,id),knots,p);for(int i=0;i<3;i++){lg(i,0)+=r.gradient[i];for(int j=0;j<3;j++)lh(i,j)+=r.hessian[3*i+j];}}for(double&x:lg.a)x/=10;for(double&x:lh.a)x/=10;auto kd=matern_with_derivatives(c,knots,knots,3,p.alpha,p.range);Matrix ki[3]={Matrix(100,100),kd.alpha,kd.range};Matrix kij[3][3]={{Matrix(100,100),Matrix(100,100),Matrix(100,100)},{Matrix(100,100),kd.aa,kd.ar},{Matrix(100,100),kd.ra,kd.rr}};Matrix W=solve_spd(kd.value,identity(100)),u=matmul(W,mu);Matrix cg(3,1),ch(3,3);for(int i=1;i<3;i++){cg(i,0)=tr(matmul(W,ki[i]))-dot(u,matmul(ki[i],u))-tr(matmul(matmul(matmul(W,ki[i]),W),sig));for(int j=1;j<3;j++){ch(i,j)=tr(matmul(W,kij[i][j]))-tr(matmul(matmul(matmul(W,ki[j]),W),ki[i]))-dot(u,matmul(kij[i][j],u))+dot(u,matmul(matmul(ki[j],W),matmul(ki[i],u)))+dot(u,matmul(matmul(ki[i],W),matmul(ki[j],u)))+tr(matmul(matmul(matmul(matmul(W,ki[j]),W),ki[i]),matmul(W,sig)))+tr(matmul(matmul(matmul(matmul(W,ki[i]),W),ki[j]),matmul(W,sig)))-tr(matmul(matmul(matmul(W,kij[i][j]),W),sig));}}
Matrix rawg=lg;for(double&x:rawg.a)x*=10;add(rawg,cg);Matrix rawh=lh;for(double&x:rawh.a)x*=10;add(rawh,ch);Eig e=jacobi(rawh);Matrix mod(3,3);Matrix ep(3,1),emp(3,1);for(int j=0;j<3;j++){ep(j,0)=e.d[j];double d=std::max(std::abs(e.d[j]),.01);emp(j,0)=d;for(int a=0;a<3;a++)for(int b=0;b<3;b++)mod(a,b)+=e.v(a,j)*d*e.v(b,j);}Matrix direction=solve_spd(mod,rawg);Matrix updated(3,1);updated(0,0)=p.delta-direction(0,0);updated(1,0)=p.alpha-direction(1,0);updated(2,0)=p.range-direction(2,0);double elg=err(lg,load(f/"p_initial_global_local_gradient.txt")),elh=err(lh,load(f/"p_initial_global_local_hessian.txt")),ecg=err(cg,load(f/"p_initial_global_correction_gradient.txt")),ech=err(ch,load(f/"p_initial_global_correction_hessian.txt")),erg=err(rawg,load(f/"p_initial_global_raw_gradient.txt")),erh=err(rawh,load(f/"p_initial_global_raw_hessian.txt")),ee=err(ep,load(f/"p_initial_global_raw_eigenvalues.txt")),eme=err(emp,load(f/"p_initial_global_modified_eigenvalues.txt")),emh=err(mod,load(f/"p_initial_global_modified_hessian.txt")),ed=err(direction,load(f/"p_initial_global_newton_direction.txt")),eu=err(updated,load(f/"p_initial_joint_updated_delta_alpha_beta.txt"));std::cout<<std::setprecision(17)<<"LOCAL_GRAD="<<elg<<"\nLOCAL_HESS="<<elh<<"\nCORR_GRAD="<<ecg<<"\nCORR_HESS="<<ech<<"\nRAW_GRAD="<<erg<<"\nRAW_HESS="<<erh<<"\nEIG="<<ee<<"\nMOD_EIG="<<eme<<"\nMOD_HESS="<<emh<<"\nDIRECTION="<<ed<<"\nUPDATED="<<eu<<"\nP_GLOBAL_NEWTON_PARITY="<<(std::max({elg,elh,ecg,ech,erg,erh,ee,eme,emh,ed,eu})<1e-8?"PASS":"FAIL")<<"\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
